WITH with_dims AS (SELECT a.id, a.order_id, a.status, d.status AS order_status, d.order_date, d.amount AS order_amount FROM payments a INNER JOIN orders d ON a.order_id = d.id) SELECT DATE_TRUNC('QUARTER', order_date) AS quarter_start, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(order_amount, ARRAY(0.25, 0.5, 0.75)) AS order_amount_quartiles FROM with_dims GROUP BY DATE_TRUNC('QUARTER', order_date) HAVING distinct_ids > 1 ORDER BY quarter_start DESC;
